CREATE TABLE `organizations` (`id` CHAR(36) NOT NULL, `name` VARCHAR(160) NOT NULL, `slug` VARCHAR(80) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, UNIQUE INDEX `organizations_slug_key`(`slug`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `departments` (`id` CHAR(36) NOT NULL, `organization_id` CHAR(36) NOT NULL, `name` VARCHAR(120) NOT NULL, UNIQUE INDEX `departments_organization_id_name_key`(`organization_id`,`name`), PRIMARY KEY (`id`), CONSTRAINT `departments_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `teams` (`id` CHAR(36) NOT NULL, `organization_id` CHAR(36) NOT NULL, `department_id` CHAR(36) NULL, `name` VARCHAR(120) NOT NULL, UNIQUE INDEX `teams_organization_id_name_key`(`organization_id`,`name`), INDEX `teams_department_id_idx`(`department_id`), PRIMARY KEY (`id`), CONSTRAINT `teams_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `teams_department_id_fkey` FOREIGN KEY (`department_id`) REFERENCES `departments`(`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `users` (`id` CHAR(36) NOT NULL, `email` VARCHAR(254) NOT NULL, `password_hash` VARCHAR(255) NOT NULL, `display_name` VARCHAR(120) NOT NULL, `role` ENUM('ADMIN','MANAGER','EMPLOYEE') NOT NULL DEFAULT 'EMPLOYEE', `status` ENUM('ACTIVE','SUSPENDED') NOT NULL DEFAULT 'ACTIVE', `locale` VARCHAR(5) NOT NULL DEFAULT 'en', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, `organization_id` CHAR(36) NULL, `department_id` CHAR(36) NULL, `team_id` CHAR(36) NULL, UNIQUE INDEX `users_email_key`(`email`), INDEX `users_role_status_idx`(`role`,`status`), INDEX `users_organization_id_role_status_idx`(`organization_id`,`role`,`status`), INDEX `users_department_id_idx`(`department_id`), INDEX `users_team_id_idx`(`team_id`), PRIMARY KEY (`id`), CONSTRAINT `users_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT `users_department_id_fkey` FOREIGN KEY (`department_id`) REFERENCES `departments`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT `users_team_id_fkey` FOREIGN KEY (`team_id`) REFERENCES `teams`(`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `audit_logs` (`id` CHAR(36) NOT NULL, `organization_id` CHAR(36) NULL, `actor_id` CHAR(36) NULL, `action` VARCHAR(100) NOT NULL, `target_type` VARCHAR(80) NULL, `target_id` VARCHAR(100) NULL, `result` VARCHAR(30) NOT NULL, `metadata` JSON NULL, `ip_address` VARCHAR(45) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `audit_logs_organization_id_created_at_idx`(`organization_id`,`created_at`), INDEX `audit_logs_actor_id_created_at_idx`(`actor_id`,`created_at`), INDEX `audit_logs_action_created_at_idx`(`action`,`created_at`), PRIMARY KEY (`id`), CONSTRAINT `audit_logs_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, CONSTRAINT `audit_logs_actor_id_fkey` FOREIGN KEY (`actor_id`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `tasks` (`id` CHAR(36) NOT NULL, `organization_id` CHAR(36) NOT NULL, `title` VARCHAR(180) NOT NULL, `description` TEXT NULL, `priority` ENUM('LOW','MEDIUM','HIGH','URGENT') NOT NULL DEFAULT 'MEDIUM', `status` ENUM('TODO','IN_PROGRESS','BLOCKED','COMPLETED','CANCELLED') NOT NULL DEFAULT 'TODO', `progress` TINYINT UNSIGNED NOT NULL DEFAULT 0, `deadline` DATETIME(3) NULL, `assignee_id` CHAR(36) NOT NULL, `created_by_id` CHAR(36) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, `deleted_at` DATETIME(3) NULL, INDEX `tasks_organization_id_status_deadline_idx`(`organization_id`,`status`,`deadline`), INDEX `tasks_assignee_id_status_deleted_at_idx`(`assignee_id`,`status`,`deleted_at`), PRIMARY KEY (`id`), CONSTRAINT `tasks_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `tasks_assignee_id_fkey` FOREIGN KEY (`assignee_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `tasks_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `task_notes` (`id` CHAR(36) NOT NULL, `task_id` CHAR(36) NOT NULL, `author_id` CHAR(36) NOT NULL, `content` VARCHAR(2000) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `task_notes_task_id_created_at_idx`(`task_id`,`created_at`), PRIMARY KEY (`id`), CONSTRAINT `task_notes_task_id_fkey` FOREIGN KEY (`task_id`) REFERENCES `tasks`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `task_notes_author_id_fkey` FOREIGN KEY (`author_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `notifications` (`id` CHAR(36) NOT NULL, `organization_id` CHAR(36) NOT NULL, `user_id` CHAR(36) NOT NULL, `type` ENUM('TASK_ASSIGNED','TASK_UPDATED','DEADLINE_APPROACHING','SESSION_STARTED','SESSION_ENDED','AI_ANALYSIS_COMPLETED') NOT NULL, `title_key` VARCHAR(100) NOT NULL, `data` JSON NULL, `read_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `notifications_user_id_read_at_created_at_idx`(`user_id`,`read_at`,`created_at`), INDEX `notifications_organization_id_created_at_idx`(`organization_id`,`created_at`), PRIMARY KEY (`id`), CONSTRAINT `notifications_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `work_sessions` (`id` CHAR(36) NOT NULL, `organization_id` CHAR(36) NOT NULL, `employee_id` CHAR(36) NOT NULL, `status` ENUM('ACTIVE','PAUSED','ENDED') NOT NULL, `started_at` DATETIME(3) NOT NULL, `ended_at` DATETIME(3) NULL, `last_event_at` DATETIME(3) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, INDEX `work_sessions_organization_id_started_at_idx`(`organization_id`,`started_at`), INDEX `work_sessions_employee_id_status_idx`(`employee_id`,`status`), PRIMARY KEY (`id`), CONSTRAINT `work_sessions_employee_id_fkey` FOREIGN KEY (`employee_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `agent_events` (`id` CHAR(36) NOT NULL, `organization_id` CHAR(36) NOT NULL, `employee_id` CHAR(36) NOT NULL, `session_id` CHAR(36) NOT NULL, `type` ENUM('SESSION_STARTED','SESSION_PAUSED','SESSION_RESUMED','SESSION_ENDED') NOT NULL, `occurred_at` DATETIME(3) NOT NULL, `payload` JSON NULL, `received_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `agent_events_organization_id_received_at_idx`(`organization_id`,`received_at`), INDEX `agent_events_session_id_occurred_at_idx`(`session_id`,`occurred_at`), PRIMARY KEY (`id`), CONSTRAINT `agent_events_employee_id_fkey` FOREIGN KEY (`employee_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `agent_events_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `work_sessions`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `refresh_tokens` (`id` CHAR(36) NOT NULL, `token_hash` CHAR(64) NOT NULL, `user_id` CHAR(36) NOT NULL, `expires_at` DATETIME(3) NOT NULL, `revoked_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `refresh_tokens_token_hash_key`(`token_hash`), INDEX `refresh_tokens_user_id_expires_at_idx`(`user_id`,`expires_at`), PRIMARY KEY (`id`), CONSTRAINT `refresh_tokens_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
